"""Prepend this iteration's results without rewriting historical documentation bytes."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];O=ROOT/'docs/verification/poloz-1.8.3.2'
def prepend(path,text):
 p=ROOT/path;old=p.read_bytes();prefix=text.encode('utf-8')
 if old.startswith(prefix.split(b'\n')[0]):return
 p.write_bytes(prefix+old)
def main():
 gate=json.loads((O/'resource-gates.json').read_text(encoding='utf-8'))
 assert gate['status']=='PASS'
 receipt=json.loads((O/'polymc-installation.json').read_text(encoding='utf-8-sig'))
 assert receipt['status']=='PASS' and receipt['sha256']==gate['sha256']
 common=f"Clean build PASS; 834 native geometry/policy assertions, 112 block state/physics assertions, 23 финальных headless GameTests и {gate['checks']} resource/production checks PASS. Всего 12 headless JVM запусков (10 завершённых успешно, 1 bootstrap failure, 1 исправленный runtime crash); загруженных GameTestServer миров 11, клиентских запусков 0. Реальный multiplayer/перезаход/визуал/впечатление от звука — NOT_RUN; MSPT/FPS — NOT_MEASURED. PolyMC Testing обновлён без запуска, предыдущая 1.8.3 сохранена вне mods. [Отчёт](verification/poloz-1.8.3.2/REPORT.md)."
 prepend('docs/PROJECT_STATUS.md',"## Поражённая земля и Великий Полоз — 1.8.3.1 / 1.8.3.2, 2026-10-12\n\nДобавлены 12 постоянных mor-блоков с переносом состояний, ванильным дропом и локальными порогами 3/5 секунд. Моровой рог получает реальный рецепт и дропы компонентов, подтверждение/60-tick hold, переносимый флаг первого использования, повторную стоимость 4 праха и авторский 9-секундный сценарий. Один 3000-HP Полоз с 24 сегментами/3 шрамами, фазами 70/30%, шестью атаками, реальными разрушениями/заражением, временной войной мобов/тремя богатырями, сохранением события, трофеями и Книгой. Идентификаторы прежнего контента сохранены; временный MorZone 1.8.2 не заменён постоянным заражением.\n\n"+common+"\n\n")
 prepend('docs/ROADMAP.md',"## 1.8.3.1 / 1.8.3.2 — требования архива реализованы, игровая приёмка открыта\n\nProduction включает постоянные поражённые блоки, Моровой рог и Великого Полоза. Автоматические результаты ниже не закрывают ручной игровой Definition of Done: нужны полный бой, 2 реальных клиента, реальный перезаход, проверка внешнего вида/звука и измеренная нагрузка. Будущие измерения, Ад, Горыныч и крафты 1.9 не добавлены.\n\n"+common+"\n\n")
 prepend('docs/ARCHITECTURE.md',"## Постоянное поражение и мировой Полоз — 1.8.3.2\n\n`MorBlocks` — точное отображение 12 прототипов/state properties, отдельные регистрации/ванильный lootFrom; `MorBlockExposure` — player-local server sampling раз в 20t. `PolozEvent` — одно Overworld SavedData с подготовкой 180t, UUID/commit receipt/refund map, участниками, cooldown и максимум 16 temporary region tickets. `GreatPoloz` — один health owner (getMaxHealth=3000 без изменения глобального атрибута), NeoForge PartEntity[27], arc-length history, synced compound track каждые 4t, independent attacker cooldown, serial attack scheduler. `PolozWorldImpact` — deduplicated очереди 2048/2048, бюджеты 32/48, максимум один контейнер за тик; обычные destroyBlock/setBlock, без rollback terrain. Прежние временные зоны 1.8.2 сохраняют свой lifecycle.\n\n`PolozAim` направляет прежние боевые действия героев в реальную зону, damage проверяет первый пересечённый AABB. `PolozEvents` даёт временные target/melee/flee goals; обе точки ограничения (`HeroCalls` и `marinka/StoryPolicy`) согласованы на три core-героя только во время события. Common не загружает клиентские рендереры/камеру; новые client handlers только Dist.CLIENT. Тестовые source sets из tools не входят в production. Генераторы mor_blocks_assets/poloz_assets воспроизводят текущие ресурсы.\n\n"+common+"\n\n")
 prepend('CHANGELOG.md',"## 1.8.3.2 — Великий Полоз (включая 1.8.3.1), 2026-10-12\n\n12 поражённых блоков, рог с точным рецептом/дропами/подтверждением, мировой multipart-босс 3000 HP/40 блоков, шесть атак и постоянные последствия. Native/offline/23 headless/production gates PASS, PolyMC Testing обновлён с backup. Клиент не запускался; ручная приёмка и MSPT/FPS открыты. Старые registry IDs сохранены. Подробности: docs/verification/poloz-1.8.3.2/REPORT.md.\n\n")
 with (O/'REPORT.md').open('a',encoding='utf-8') as f:f.write(f"\n## Финальный артефакт и установка\n\n`build/libs/slavicmyths-1.8.3.2.jar`, SHA256 `{gate['sha256']}`. Clean build, 834 native checks / 4 models, 112 block checks, 23 GameTests, {gate['checks']} production/resource gates — PASS. {gate['event_subscribers']} непустых event subscribers.\n\nПрофиль `{receipt['instance']}`. Установленный JAR `{receipt['installed_jar']}`; backup `{receipt['backup']}`. {receipt['other_files_preserved']} остальных файлов профиля сохранены побайтно, старый профиль 1.16.5 и миры не менялись. Установщик ничего не запускал. Полная квитанция: polymc-installation.json.\n")
 print('Documentation updated; user history bytes preserved.')
